# --- 2. HELPER FUNCTION ---

# Converts a filename like 'ai-bio-generator.html' to a pretty name 'AI Bio Generator'
function Convert-FileNameTo-PrettyName($fileName) {
    $name = $fileName.Replace(".html", "")
    $parts = $name.Split('-')
    $capitalizedParts = $parts | ForEach-Object { 
        $word = $_
        [System.Globalization.CultureInfo]::CurrentCulture.TextInfo.ToTitleCase($word) 
    }
    return $capitalizedParts -join " "
}


# --- 3. SCRIPT EXECUTION ---

Write-Host "Starting JSON generation process..."

# Initialize main data structures
$navigationObject = [pscustomobject]@{
    siteName   = "Bluetext.in"
    totalTools = 0
    categories = @()
}
$toolsList = @()
$totalToolCount = 0

# Process each category
foreach ($categoryId in $allToolsByCategory.Keys) {
    
    # Get category configuration
    $config = $categoriesConfig[$categoryId]
    if (-not $config) {
        Write-Warning "No configuration found for category ID '$categoryId'. Skipping."
        continue
    }

    $categoryObject = [pscustomobject]@{
        id    = $categoryId
        name  = $config.Name
        icon  = $config.Icon
        tools = @()
    }

    # Process each tool in the category
    $toolFiles = $allToolsByCategory[$categoryId]
    foreach ($toolFile in $toolFiles) {
        $prettyName = Convert-FileNameTo-PrettyName $toolFile
        
        # Define the URL based on the category folder
        $toolUrl = "/tools/$categoryId/$toolFile"
        if ($categoryId -eq "games") { # Special case for games folder
             $toolUrl = "/games/$toolFile"
        }

        # --- Populate navigation.json entry ---
        $navToolObject = [pscustomobject]@{
            name = $prettyName
            url  = $toolUrl
        }
        $categoryObject.tools += $navToolObject

        # --- Populate tools.json entry ---
        $toolMetadataObject = [pscustomobject]@{
            name        = $prettyName
            category    = $config.Name
            description = "A free online tool to $prettyName. More description coming soon."
            keywords    = @($prettyName.ToLower(), $config.Name.ToLower(), "free tool", "online")
            url         = $toolUrl
        }
        $toolsList += $toolMetadataObject
        
        $totalToolCount++
    }
    
    $navigationObject.categories += $categoryObject
}

$navigationObject.totalTools = $totalToolCount

# --- 4. SAVE FILES ---

# Ensure the target directory exists
$dataDir = "assets/data"
if (-not (Test-Path $dataDir)) {
    Write-Host "Creating directory: $dataDir"
    New-Item -ItemType Directory -Path $dataDir | Out-Null
}

# Save navigation.json
$navJsonPath = Join-Path $dataDir "navigation.json"
$navigationObject | ConvertTo-Json -Depth 10 | Out-File -FilePath $navJsonPath -Encoding utf8
Write-Host "Successfully created '$navJsonPath' with $totalToolCount tools." -ForegroundColor Green

# Save tools.json
$toolsJsonPath = Join-Path $dataDir "tools.json"
$toolsList | ConvertTo-Json -Depth 10 | Out-File -FilePath $toolsJsonPath -Encoding utf8
Write-Host "Successfully created '$toolsJsonPath' with metadata for $totalToolCount tools." -ForegroundColor Green

Write-Host "JSON data generation complete!"
